create table if not exists public.prometeo_backlog_objects (
  backlog_id integer primary key,
  source_key text not null unique,
  source_ref text not null unique,
  title text not null,
  summary text not null default '',
  source_status text not null,
  base_state text not null references public.prometeo_backlog_states(state),
  source_payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint prometeo_backlog_objects_source_key_check check (source_key = 'BACKLOG-' || backlog_id::text)
);

comment on table public.prometeo_backlog_objects is
'Canonical online identity for every durable Cognitive Forge backlog item. source_key/source_ref are stable; live state is projected by prometeo_backlog_objects_live.';

alter table public.prometeo_backlog_objects enable row level security;
drop policy if exists "read prometeo backlog objects" on public.prometeo_backlog_objects;
create policy "read prometeo backlog objects"
on public.prometeo_backlog_objects for select
to anon, authenticated using (true);

on conflict (backlog_id) do update set
 source_key=excluded.source_key,
 source_ref=excluded.source_ref,
 title=excluded.title,
 summary=excluded.summary,
 source_status=excluded.source_status,
 base_state=excluded.base_state,
 source_payload=excluded.source_payload,
 updated_at=now();

create or replace view public.prometeo_backlog_objects_live
with (security_invoker=true)
as
with projected as (
 select
  b.backlog_id,b.source_key,b.source_ref,b.title,b.summary,b.source_status,b.source_payload,
  case
   when coalesce(fs.state,'')='DONE' or fs.completed_at is not null or j.status='DONE' then 'DONE'
   when j.status='LEASED' then 'WORKING'
   when j.status='READY' then 'READY'
   when j.status='BLOCKED' then 'DESIGNED'
   when fs.materialized_job_key is not null then 'READY'
   else b.base_state
  end as state,
  fs.state as frontier_state,
  fs.materialized_job_key as job_key,
  fs.materialized_at,
  fs.completed_at,
  b.created_at,b.updated_at
 from public.prometeo_backlog_objects b
 left join public.prometeo_frontier_sources fs on fs.source_key=b.source_key
 left join public.prometeo_jobs j on j.job_key=fs.materialized_job_key
)
select p.*, s.ordinal as state_ordinal, s.is_terminal
from projected p
join public.prometeo_backlog_states s on s.state=p.state;

comment on view public.prometeo_backlog_objects_live is
'Live canonical backlog objects: stable BACKLOG-N identity/reference plus state projected from current frontier/job state and canonical backlog-state catalog.';

grant select on public.prometeo_backlog_objects_live to anon, authenticated;